import {materialParameters,materialFloatProperty,materialDefaults,surfaceInputs} from './material-runtime.js';
import {primaryLightComponent,primaryOwnedLight,ownedLight} from './light-parameter-state.js';
const floatProperties=new Set([...surfaceInputs.filter(p=>p.type==='float').map(p=>p.key),'emissiveIntensity']);
export function materialSequenceParameter(data,name){if(!data)return null;const parameter=materialParameters(data).find(p=>p.name===name);if(parameter)return parameter.type==='float'&&Number.isFinite(parameter.value)?{key:'parameter:'+parameter.name,parameter:parameter.name,value:parameter.value}:null;const property=materialFloatProperty(name),value=data.surface?.[property]??materialDefaults[property];return floatProperties.has(property)&&Number.isFinite(value)?{key:'surface:'+property,parameter:property,value}:null;}
export const sequenceLightComponentTrack=(track,component)=>({...track,type:'component',component:component.id,componentType:component.type,property:'intensity'});
// Cached per active VM/actor/group/material identity. Alias spellings share one
// token and field, while replacing a material cannot receive an old restoration.
export class SequenceRenderParameters{
 constructor(hooks){this.hooks=hooks;this.materials=new WeakMap();}
 light(state,object,track){state.lightParameterBindings??=new WeakMap();let row=state.lightParameterBindings.get(track);if(row?.object===object&&row.track)return row.track;const component=primaryLightComponent(object,this.hooks.mesh?.(object.id)),bound=component?sequenceLightComponentTrack(track,component):null;state.lightParameterBindings.set(track,{object,track:bound});return bound;}
 plainLight(object,vm){const group=this.hooks.mesh?.(object.id),node=primaryOwnedLight(group);if(!node)return null;return {target:node,key:'intensity',options:()=>({mix:'linear',read:()=>node.intensity,apply:value=>{node.intensity=Math.max(0,value);},valid:()=>vm.object(object.id)===object&&this.hooks.mesh(object.id)===group&&ownedLight(group,node)&&!group.userData.disposed})};}
 material(object,name,vm,b){const group=this.hooks.mesh?.(object.id),data=group?.userData.materialData;if(!data)return {target:object,key:'material:'+name,options:()=>({mix:'linear',read:()=>this.hooks.captureParameter(object.id,'material',name),apply:value=>this.hooks.operation('materialFloat',{target:object.id,parameter:name,value},b,vm),valid:()=>vm.object(object.id)===object})};let actors=this.materials.get(vm);if(!actors){actors=new WeakMap();this.materials.set(vm,actors);}let groups=actors.get(object);if(!groups){groups=new WeakMap();actors.set(object,groups);}let sources=groups.get(group);if(!sources){sources=new WeakMap();groups.set(group,sources);}let record=sources.get(data);if(!record){record={target:{},names:new Map()};sources.set(data,record);}let descriptor=record.names.get(name);if(!descriptor){const parameter=materialSequenceParameter(data,name);if(!parameter)throw Error('시퀀스 머테리얼 Float 파라미터를 확인하세요: '+name);descriptor={target:record.target,key:'material:'+parameter.key,options:()=>({mix:'linear',read:()=>materialSequenceParameter(data,name)?.value,apply:value=>this.hooks.operation('materialFloat',{target:object.id,parameter:name,value},b,vm),valid:()=>vm.object(object.id)===object&&this.hooks.mesh(object.id)===group&&group.userData.materialData===data&&!group.userData.disposed})};record.names.set(name,descriptor);}return descriptor;}
}
